import java.util.*;

class Solution {
    public List<List<Integer>> distinctPicks(int[] nums) {
        Arrays.sort(nums);                          // equal values become neighbours
        List<List<Integer>> out = new ArrayList<>();
        go(nums, 0, new ArrayList<Integer>(), out);
        return out;
    }

    private void go(int[] nums, int start, List<Integer> cur, List<List<Integer>> out) {
        out.add(new ArrayList<>(cur));              // every partial pick is an answer
        for (int j = start; j < nums.length; j++) {
            if (j > start && nums[j] == nums[j - 1]) continue; // same value at same depth
            cur.add(nums[j]);
            go(nums, j + 1, cur, out);
            cur.remove(cur.size() - 1);             // undo the choice
        }
    }
}

