class Solution:
    def distinctPicks(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        out, cur = [], []
        def go(i):
            out.append(cur[:])
            for j in range(i, len(nums)):
                if j > i and nums[j] == nums[j - 1]: continue
                cur.append(nums[j]); go(j + 1); cur.pop()
        go(0)
        return out

