function distinctPicks(nums) {
  const n = nums.length, seen = new Set(), out = [];
  for (let m = 0; m < (1 << n); m++) {
    const s = []; for (let i = 0; i < n; i++) if (m >> i & 1) s.push(nums[i]);
    s.sort((a, b) => a - b); const key = s.join(",");
    if (!seen.has(key)) { seen.add(key); out.push(s); }
  }
  return out;
}
